package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

const (
	sandboxDir  = "/var/sandbox"
	quarantineDir = "/var/quarantine"
	maxFileSize = 5 * 1024 * 1024
)

type FileScanner struct {
	mu       sync.Mutex
	scanning map[string]bool
}

var scanner = &FileScanner{scanning: make(map[string]bool)}

// validatePath ensures the path is within the sandbox
func validatePath(userPath string) (string, error) {
	// Clean and resolve the path
	cleaned := filepath.Clean(userPath)
	if filepath.IsAbs(cleaned) {
		return "", fmt.Errorf("absolute paths not allowed")
	}
	// Prevent directory traversal
	if strings.Contains(cleaned, "..") {
		return "", fmt.Errorf("path traversal not allowed")
	}
	fullPath := filepath.Join(sandboxDir, cleaned)
	// Verify it resolves within sandbox
	resolved, err := filepath.EvalSymlinks(fullPath)
	if err != nil {
		return "", fmt.Errorf("path resolution failed: %v", err)
	}
	if !strings.HasPrefix(resolved, sandboxDir) {
		return "", fmt.Errorf("path escapes sandbox")
	}
	return fullPath, nil
}

// checkFileProperties validates file before processing
func checkFileProperties(path string) error {
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("stat failed: %v", err)
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("not a regular file")
	}
	if info.Size() > maxFileSize {
		return fmt.Errorf("file too large: %d bytes", info.Size())
	}
	if info.Size() == 0 {
		return fmt.Errorf("file is empty")
	}
	return nil
}

// computeHash reads the file and computes SHA-256
func computeHash(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// moveToQuarantine moves suspicious files
func moveToQuarantine(path string, hash string) error {
	dest := filepath.Join(quarantineDir, hash)
	return os.Rename(path, dest)
}

// scanFile performs the security scan pipeline
func scanFile(path string) (string, error) {
	scanner.mu.Lock()
	if scanner.scanning[path] {
		scanner.mu.Unlock()
		return "", fmt.Errorf("already scanning")
	}
	scanner.scanning[path] = true
	scanner.mu.Unlock()

	defer func() {
		scanner.mu.Lock()
		delete(scanner.scanning, path)
		scanner.mu.Unlock()
	}()

	// Step 1: Validate file properties
	if err := checkFileProperties(path); err != nil {
		return "", fmt.Errorf("validation failed: %v", err)
	}

	// Step 2: Brief delay for rate limiting
	time.Sleep(50 * time.Millisecond)

	// Step 3: Compute hash of file contents
	hash, err := computeHash(path)
	if err != nil {
		return "", fmt.Errorf("hash computation failed: %v", err)
	}

	return hash, nil
}

func handleScan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	filePath := r.FormValue("file_path")
	if filePath == "" {
		http.Error(w, "file_path required", http.StatusBadRequest)
		return
	}

	// Validate the path is within sandbox
	validPath, err := validatePath(filePath)
	if err != nil {
		http.Error(w, fmt.Sprintf("Invalid path: %v", err), http.StatusBadRequest)
		return
	}

	// Perform the scan
	hash, err := scanFile(validPath)
	if err != nil {
		http.Error(w, fmt.Sprintf("Scan failed: %v", err), http.StatusInternalServerError)
		return
	}

	// Check against known-bad hashes (simplified)
	knownBad := map[string]bool{
		"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855": true,
	}

	if knownBad[hash] {
		if err := moveToQuarantine(validPath, hash); err != nil {
			log.Printf("quarantine failed: %v", err)
		}
		fmt.Fprintf(w, "{\"status\": \"quarantined\", \"hash\": \"%s\"}", hash)
	} else {
		fmt.Fprintf(w, "{\"status\": \"clean\", \"hash\": \"%s\"}", hash)
	}
}

func main() {
	os.MkdirAll(sandboxDir, 0750)
	os.MkdirAll(quarantineDir, 0750)

	mux := http.NewServeMux()
	mux.HandleFunc("/scan", handleScan)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	log.Printf("File scanner starting on :8443")
	log.Fatal(server.ListenAndServeTLS("/etc/certs/server.crt", "/etc/certs/server.key"))
}
